// lab/s6/d01 —— Vue 3 与 React 的概念映射：把 12 组对照「跑」一遍给你看
//
// 跑法：
//   cd ~/www/homecube/web && node lab/s6/d01/main.mjs
//
// 这不是一张背概念的表。每一行都用真Vue 跑一次，让你看到「两个框架在同一个问题上的答案」。

import { ref, reactive, computed, watch, watchEffect, onMounted, onUnmounted,
         defineComponent, provide, inject, nextTick, shallowRef, toRefs } from 'vue'
import { createRenderer, h } from '@vue/runtime-core'
import { createMiniDom } from './_shared/minidom.mjs'

const L = (s = '') => console.log(s)
const H = (t) => L('\n===== ' + t + ' =====')

// ============ 1. 状态：useState ↔ ref ============
H('1. 状态：useState ↔ ref')
const count = ref(0)                     // React: const [count, setCount] = useState(0)
const setCount = (v) => { count.value = typeof v === 'function' ? v(count.value) : v }
L('声明：const count = ref(0)')
L('读  ：count.value = ' + count.value + '（React 是 count）')
L('写  ：count.value++，或 setCount(c => c + 1)（函数式更新两边都支持）')
setCount((c) => c + 1)
L('setCount(c => c+1) 之后 count.value = ' + count.value)
L('★ 差别只有一处：Vue 要写 .value，React 不要。')
L('  .value 存在的唯一原因是 JS 里变量名不能叫 value（那是关键字位置）。')

// ============ 2. 对象状态：useState(对象) ↔ reactive ============
H('2. 对象状态：useState({...}) ↔ reactive({...})')
const form = reactive({ name: '', amount: 0, note: '' })  // React: const [form, setForm] = useState({...})
form.name = '餐饮'
form.amount = 3000
L('form.name = ' + form.name + '，form.amount = ' + form.amount)
L('★ React 改对象必须整体换：setForm(f => ({ ...f, name: \'餐饮\' }))')
L('  Vue 直接改字段就行，Proxy 会记录「谁读了这个字段」。')
const { name: formName, amount: formAmount } = toRefs(form)
L('toRefs 解构后：formName.value = ' + formName.value + '（解构仍保持响应式，这是 reactive 唯一的安全解构法）')

// ============ 3. 派生值：useMemo ↔ computed ============
H('3. 派生值：useMemo ↔ computed')
const amount = ref(100)
let computeCalls = 0
const total = computed(() => { computeCalls++; return amount.value * 2 })
L('刚创建 computed（没人读）→ getter 执行次数 = ' + computeCalls)
L('读第 1 次 total.value = ' + total.value + '，getter 执行次数 = ' + computeCalls)
L('读第 2 次（值没变）= ' + total.value + '，getter 执行次数 = ' + computeCalls + '（缓存命中）')
amount.value = 200
L('改 amount=200 后读 = ' + total.value + '，getter 执行次数 = ' + computeCalls + '（依赖变了，重算一次）')
L('')
L('React 侧对应写法：const total = useMemo(() => amount * 2, [amount])')
L('差别一：useMemo 每次组件重渲染都会重新执行 fn（结果可能被复用）；')
L('         computed 是「没人读就不算+ 依赖没变就用缓存」。')
L('差别二（更关键）：useMemo 的 deps 必须手写，漏一个就拿到过期值，而且**不会报错**；')
L('         computed 的依赖是运行时自动收集的，getter 里读了什么就依赖什么，不存在漏写。')
L('★ 所以：能用 computed 就别用 useMemo式的手写 deps。')

H('4. 副作用：useEffect(fn, deps) ↔ watch(source, cb)')
const keyword = ref('')
let effectRuns = 0
const stopWatch = watch(keyword, () => { effectRuns++ })
L('创建 watch(keyword, cb) —— 注意它**注册时不执行**')
keyword.value = '餐'
await nextTick()
L('改 keyword 之后 effectRuns = ' + effectRuns)
L('★ useEffect 对应的是「注册时就会执行一次」的语义，所以 Vue 侧有两个对应物：')
L('  watch(keyword, cb, { immediate: true })   ← 等价于 useEffect(fn, [keyword])')
L('  watchEffect(() => {...})                 ← 等价于 useEffect(fn) （deps 自动 = [] 里读了什么就是什么）')
stopWatch()

// ============ 5. 生命周期 ============
H('5. 生命周期：useEffect ↔ onMounted/onUnmounted（本卡只列对照，d06 真跑一遍）')
const life = [
  ['useEffect(() => {}, [])',        'onMounted(fn)',                '挂载后跑一次'],
  ['useEffect 的 return () => {}',    'onUnmounted(fn)',              '卸载时跑一次'],
  ['useEffect(() => {}, [a])',        'watch(a, cb, { immediate: true })', 'a 变化时跑'],
  ['useEffect(fn) 无 deps',           'watchEffect(fn)',              '自动收集依赖'],
]
L('React'.padEnd(34) + 'Vue'.padEnd(40) + '时机')
for (const [a, b, c] of life) L(a.padEnd(34) + b.padEnd(38) + c)
L('')
L('★ 组件的 onMounted ≈ 页面的 onLoad（都只跑一次）；')
L('  页面对应的「每次显示都跑」是 onShow —— 这是 Vue 独有的第四个页面钩子。')

H('6. 依赖注入：React Context ↔ provide / inject')
// provide/inject 必须在 setup() 里调用，否则 Vue 会警告。所以这里用一个父组件来真跑。
const INJECT_KEY = 'family-snapshot'
const Consumer = defineComponent({
  setup() {
    const ctx = inject(INJECT_KEY, { familyId: '(默认值)', role: 'guest' })
    L('  在 Provider 子树里 inject → ' + JSON.stringify(ctx) + '← 拿到的是 provide 的值')
    return () => h('text', '子：' + ctx.familyId)
  },
})
const dom = createMiniDom()
// 第一棵：有 Provider
dom.mount(defineComponent({
  setup() {
    provide(INJECT_KEY, { familyId: 'fam-1', role: 'owner' })
    return () => h('view', [h(Consumer)])
  },
}))
// 第二棵：完全没有 Provider
const Orphan = defineComponent({
  setup() {
    const ctx = inject(INJECT_KEY, { familyId: '(默认值)', role: 'guest' })
    L('  在没有 Provider 的树里 inject → ' + JSON.stringify(ctx) + '← 用了默认值')
    return () => h('text', '孤儿')
  },
})
const dom2 = createMiniDom()
dom2.mount(defineComponent({ setup: () => () => h('view', [h(Orphan)]) }))
L('★ provide 只对**子树**生效：同一次运行里，上面那棵拿到了真值，下面那棵拿到默认值。')
L('★ 与 React Context 的差别：')
L('  React 里 Provider 只影响**它的子树**；Vue 的 provide 同样只对子树生效，规则一致。')
L('  但 inject 的默认值语义更明确：第二个参数给了就一定不报错，')
L('  想区分「没有 Provider」与「Provider 给了 null」要写成 inject(KEY, undefined)。')

H('7. 列表 key：两者要求完全一样')
L('v-for 里写 :key="item.id"，不是 :key="index"。')
L('  用 index 当 key，在列表头部插入一条时，后面所有项的「身份」都变了，')
L('  Vue 会以为每一行都变了而重建节点 —— 表现为输入框内容错位。')
L('  React 的 key 也是同一个道理、同一条规则、同一个原因。')
L('  本项目分类列表：key 用 category.id（UUID，稳定且唯一），绝不用数组下标。')

H('8. 零散对照表')
const pairs = [
  ['JSX',            '<template> 标签',       '结构一样，只是 JSX 全写在 .tsx，模板写在 .vue'],
  ['Fragment <>',    '<template>（多根时必须包）','Vue3 支持多根，不用 Fragment'],
  ['React.memo',     'v-memo / computed 缓存',  '思路相同：跳过无谓的重算'],
  ['useRef（非状态）','普通 let + 闭包',        '都不触发渲染'],
  ['key',            ':key',                  '同一套规则'],
  ['children',       '默认 slot',             '具名 slot 对应具名 children'],
  ['forwardRef',     'ref 属性 + defineExpose','uni-app 里少见，但调试常用'],
  ['Portal',         'uni 不支持（无 DOM 概念）','小程序没有 DOM，不能挂到 body'],
  ['ErrorBoundary',  'uni.onError / 页面兜底',  '没有组件级边界，只能全局兜'],
  ['Suspense',       'uni 异步分包 + loading',  '机制完全不同'],
  ['Redux/Pinia',    'stores/（本工程用 pinia）','都是「全局状态的单一真源」'],
  ['Next.js 路由',   'pages.json',            '★ uni 的路由是配置文件驱动的，不是文件驱动'],
]
L('React'.padEnd(20) + 'Vue'.padEnd(26) + '说明')
for (const [a, b, c] of pairs) L(a.padEnd(20) + b.padEnd(24) + c)

H('★ 最容易踩的三个「看起来一样其实不一样」')
L('1. useEffect 的清理函数 return () => ... vs onUnmounted(() => ...)')
L('   React 里依赖变化也会先清理再执行；Vue 里 watch 要自己拿 onCleanup 或用 onWatcherCleanup。')
L('2. React 的 setState 是「排队 + 批处理」，Vue 的 ref.value = 是「同步改 + 异步渲染」。')
L('   所以 Vue 里可以count.value++; console.log(count.value) 立刻看到新值，React 里不行。')
L('3. React 组件重渲染 = 函数重新执行；Vue 组件重渲染 = 只重跑 render，不重跑 setup。')
L('   ★ 这就是为什么 setup 里不能写「一次性逻辑」之外的东西：它只跑一次。')

// lab/s6/d05 —— props 与 emit：对比 React 的 props 与回调
//
// 跑法：
//   cd ~/www/homecube/web && node lab/s6/d05/main.mjs
//
// props / emit 是框架层行为，与 DOM 无关，所以用 _shared/minidom.mjs 真挂载真交互。

import { defineComponent, ref, reactive, computed, h, nextTick } from 'vue'
import { createMiniDom, render, find } from './_shared/minidom.mjs'

const L = (s = '') => console.log(s)
const H = (t) => L('\n===== ' + t + ' =====')

// ============ 子组件：props 声明 + emit 声明 ============
const CategoryRow = defineComponent({
  name: 'CategoryRow',                                  // ★ name 必须写，递归组件与 keep-alive 靠它识别
  props: {
    id: { type: String, required: true },
    name: { type: String, required: true },
    isActive: { type: Boolean, default: true },          // Boolean 有个特殊规则，见第 4 节
    sortOrder: { type: Number, default: 0 },
  },
  emits: ['archive', 'restore', 'rename'],               // ★ 声明 emits 才有类型检查 + 不会漏进 attrs
  setup(props, { emit }) {
    const label = computed(() => (props.isActive ? props.name : props.name + '（已停用）'))
    return () =>
      h('view', { class: 'row' + (props.isActive ? '' : ' off') }, [
        h('text', { class: 'name', onClick: () => emit('rename', { id: props.id, name: props.name }) }, label.value),
        h('text', {
          class: 'act',
          onClick: () => (props.isActive ? emit('archive', props.id) : emit('restore', props.id)),
        }, props.isActive ? '停用' : '恢复'),
        h('text', { class: 'ord' }, 'sort=' + props.sortOrder),
      ])
  },
})

H('1. 挂载后真实的 DOM 树（三个子组件，各自带不同 props）')
const dom = createMiniDom()
const { ctrl, root } = dom.mountFactory(() => {
  const rows = ref([
    { id: 'c-1', name: '餐饮', isActive: true, sortOrder: 10 },
    { id: 'c-2', name: '餐饮(家用)', isActive: true, sortOrder: 11 },
    { id: 'c-3', name: '停用的分类', isActive: false, sortOrder: 12 },
  ])
  const log = []
  const Page = defineComponent({
    setup: () => ({ rows, log }),
    render() {
      return h('view', [
        ...this.rows.map((r) => h(CategoryRow, {
          key: r.id,                       // ★ 用 id，不用 index
          id: r.id, name: r.name, isActive: r.isActive, sortOrder: r.sortOrder,
          onArchive: (id) => { this.log.push('收到 archive: ' + id); r.isActive = false },
          onRestore: (id) => { this.log.push('收到 restore: ' + id); r.isActive = true },
          onRename: (p) => { this.log.push('收到 rename: ' + p.id + ' / ' + p.name) },
        })),
      ])
    },
  })
  return { component: Page, ctrl: { rows, log } }
})
L(render(root))

H('2. props 是单向的：子组件只能读，改必须由父组件发起')
const before = ctrl.rows.value[0].name
L('第一行的 name = ' + before)
L('现在从「父组件」改数据（也就是改了子组件看到的 props）：')
ctrl.rows.value[0].name = '餐饮（改名）'
await nextTick()
L('  DOM：')
L(render(find(root, 'view', 'row')))
L('★ 关键机制：父组件的 rows[0] 这个对象「就是」子组件 props 的来源，')
L('  所以「改 props」在 Vue 里等价于「改父组件的数据」——它不是一条独立通路。')
L('')
L('★ 那「在子组件里写 props.xxx = y」会怎样？Vue 会警告且不生效：')
const Silent = defineComponent({
  props: { label: String },
  setup(props) {
    // 这行会触发 Vue 警告：Set operation on key "label" failed: target is readonly.
    props.label = '子组件偷偷改的'
    return () => h('text', props.label)
  },
})
const domSilent = createMiniDom()
domSilent.mount(Silent, { label: '父组件给的' })
L('  子组件渲染出来的是：' + render(domSilent.root).trim().split('\n').pop().trim())
L('★ 所以 React 里的「props 是只读的」这条规则，Vue 也有，只是')
L('  它靠 Proxy 的 set 拦截 + 开发期警告来保证，而不是靠类型系统。')

H('3. ★emit 的完整链路：子组件发 → 父组件收 → 父组件改数据 → 全树更新')
L('当前 rows 状态：')
ctrl.rows.value.forEach((r) => L('  ' + r.id + ' ' + r.name + ' isActive=' + r.isActive))
L('')
L('模拟点击第一行的「停用」按钮（onClick → emit("archive", id)）：')
ctrl.log.length = 0
find(root, 'text', 'act').props.onClick()
await nextTick()
L('  父组件收到的回调：' + (ctrl.log.length ? ctrl.log.join('、') : '（无）'))
L('  改完之后的 DOM：')
L(render(root))

H('4. ★props 声明的坑（每一行都是实测结果，不是记忆）')
const probe = (Comp, props) => {
  const d = createMiniDom()
  d.mount(Comp, props)
  const line = render(d.root).split('\n').filter((l) => l.includes('"')).pop()
  return line ? line.trim().replace(/^"/, '').replace(/"$/, '') : '(空)'
}
const BoolWithDefault = defineComponent({
  props: { flag: { type: Boolean, default: true } },
  setup: (p) => () => h('text', 'flag=' + JSON.stringify(p.flag)),
})
const BoolNoDefault = defineComponent({
  props: { flag: Boolean },
  setup: (p) => () => h('text', 'flag=' + JSON.stringify(p.flag)),
})
const StrNoDefault = defineComponent({
  props: { s: String },
  setup: (p) => () => h('text', 's=' + JSON.stringify(p.s)),
})
const NumNoDefault = defineComponent({
  props: { n: Number },
  setup: (p) => () => h('text', 'n=' + JSON.stringify(p.n)),
})
L('props 声明'.padEnd(40) + '父组件的传法'.padEnd(22) + '子组件拿到')
const cases = [
  ['{ type: Boolean, default: true }', {}, BoolWithDefault],
  ['{ type: Boolean, default: true }', { flag: false }, BoolWithDefault],
  ['Boolean（无 default）', {}, BoolNoDefault],
  ['String（无 default）', {}, StrNoDefault],
  ['String（无 default）', { s: '' }, StrNoDefault],
  ['Number（无 default）', {}, NumNoDefault],
]
for (const [decl, props, Comp] of cases) {
  L(decl.padEnd(40) + JSON.stringify(props).padEnd(20) + probe(Comp, props))
}
L('')
L('★ 坑1（实测结论，和网上多数文章说的不一样）：')
L('  只有「Boolean 类型 + 没写 default」时，不传才会变成 false；')
L('  只要写了 default:true，不传拿到的就是 true。')
L('  所以「不传 = true」用 { type: Boolean, default: true } 就够了，')
L('  不需要 [Boolean, null] 那种写法。真正会咬人的是**不写 default** 的 Boolean：')
L('  它不传时是 false，而你会以为是 undefined。')
L('')
L('★ 坑2：必填与类型不匹配都只是「警告 + 照常渲染」')
const Req = defineComponent({
  props: { id: { type: String, required: true } },
  setup: (p) => () => h('text', 'id=' + JSON.stringify(p.id)),
})
L('required 的 id 缺失 → 控制台 warn，子组件拿到 ' + probe(Req, {}))
L('传了数字 123        → 控制台 warn，子组件拿到 ' + probe(Req, { id: 123 }) + '（值照传，不转换）')
L('★ 也就是说 prop 的类型声明只是「开发期护栏」，它不会替你转换任何东西。')
L('  真要防住脏数据，必须在提交前自己校验（S7 d7 表单页会做）。')
L('')
L('★ 坑3：对象类型的 prop 传的是「同一个引用」')
const shared = reactive({ name: '餐饮', children: [] })
const Kid = defineComponent({
  props: { item: Object },
  setup: (p) => () => h('text', 'name=' + p.item.name + ' children=' + p.item.children.length),
})
const d3 = createMiniDom()
d3.mount(Kid, { item: shared })
L('  挂载后：' + probe(Kid, { item: shared }))
shared.children.push('子项A')
await nextTick()
L('  父组件往同一个对象 push 之后，子组件看到：' + probe(Kid, { item: shared }))
L('★ 机理：传的是引用，两边看到的是同一个对象。所以「父组件改 → 子组件自动更新」')
L('  在对象 prop 上成立；但这也意味着子组件改它同样会「意外地」影响父组件。')
L('  本项目分类列表的规矩：子组件只读 props，绝不往里写；')
L('  要改就emit 给父组件，由父组件改数据 —— 与 React 的规矩完全一致。')

H('5. React 对照表')
const table = [
  ['<Child a={1} />',          '<Child :a="1" />',            '冒号是「绑定表达式」，没有冒号是字符串'],
  ['a={"x": 1}',              ':a="{ x: 1 }"',               '传对象必须带冒号'],
  ['onSave={fn}',              '@save="fn" 或 :onSave="fn"',  'uni-app 推荐 @save'],
  ['children',                 '默认 slot',                   '具名 slot ↔ 具名 children'],
  ['key={item.id}',            ':key="item.id"',              '规则完全一致：都用稳定 id，不用下标'],
  ['组件名必须大写',            '基本没这个限制',               'Vue 靠 import 区分，不靠大小写'],
  ['props 改了要 setState',    '直接读就是响应式的',           '这是 Vue 比 React 省事的地方'],
  ['useState + 回调',         'props（父→子）+ emit（子→父）', '数据流方向与 React 一致'],
  ['memo / useCallback',       'computed / v-memo',           '都靠「值没变就跳过」实现'],
]
L('React'.padEnd(24) + 'Vue'.padEnd(32) + '备注')
for (const [a, b, c] of table) L(a.padEnd(24) + b.padEnd(30) + c)
L('')
L('★ 一句话总结数据流：React 的 props + 回调 = Vue 的 props + emit，方向完全一样')
L('  （父 → 子 传数据，子 → 父 传事件）。所以你已有的心智模型可以直接用。')
L('')
L('★ 为什么不多给：每多一个 props，父组件就要多传一份；')
L('  数据放子组件自己内部（比如展开状态）就放在本地，不要提到父组件。')

// lab/s6/d06 —— 生命周期：onMounted / onUnmounted 与 useEffect 的 mount/unmount
//
// 跑法：
//   cd ~/www/homecube/web && node lab/s6/d06/main.mjs
//
// _shared/minidom.mjs 是一个 60 行的「无 DOM 渲染器」：它用 Vue 官方的 createRenderer
// 造了一套宿主对象，于是组件可以被真的挂载、真的响应式更新、真的卸载。
// 生命周期是**框架层**行为，与有没有真浏览器无关，所以这里跑出来的就是真行为。

import { defineComponent, ref, onMounted, onUnmounted, onBeforeMount,
         onBeforeUnmount, onActivated, onDeactivated, h, nextTick, KeepAlive } from 'vue'
import { createMiniDom, render, find } from './_shared/minidom.mjs'

const L = (s = '') => console.log(s)
const H = (t) => L('\n===== ' + t + ' =====')

const log = []
const step = (s) => { log.push(s); L('  · ' + s) }

// ---------- 组件：带完整生命周期钩子 ----------
const Timer = defineComponent({
  props: { label: String },
  setup(props) {
    onBeforeMount(() => step('onBeforeMount（DOM 还没建好）'))
    onMounted(() => step('onMounted（DOM 已就绪，可以量尺寸/调 setData）'))
    onBeforeUnmount(() => step('onBeforeUnmount（还没拆，先解绑）'))
    onUnmounted(() => step('onUnmounted（已拆干净）'))
    return () => h('view', { class: 'timer' }, 'timer:' + props.label)
  },
})

H('1. 挂载：钩子的触发顺序')
L('（把 Timer 挂到页面上）')
const dom = createMiniDom()
const { ctrl, root } = dom.mountFactory(() => {
  const show = ref(true)
  const count = ref(0)
  const Page = defineComponent({
    setup() {
      onMounted(() => step('页面 onMounted（父）'))
      onUnmounted(() => step('页面 onUnmounted（父）'))
      return { show, count }
    },
    render() {
      return h('view', [
        this.show ? h(Timer, { label: 'A' }) : h('text', '（计时器已移除）'),
        h('text', { class: 'cnt' }, 'count=' + this.count),
      ])
    },
  })
  return { component: Page, ctrl: { show, count } }
})
