H('4. keep-alive：这是 Vue 独有的第三种状态')
L('（用 Vue 真正的 <KeepAlive> 包一层，然后在两个子组件之间来回切）')
const dom2 = createMiniDom()
const klog = []
const mkPage = (name) => defineComponent({
  name,
  setup() {
    onMounted(() => klog.push(name + ' mount'))
    onActivated(() => klog.push(name + ' activated（显示了）'))
    onDeactivated(() => klog.push(name + ' deactivated（隐藏了，但没销毁）'))
    onUnmounted(() => klog.push(name + ' unmount（真销毁）'))
    return () => h('text', name)
  },
})
const PageA = mkPage('A'), PageB = mkPage('B')
const w = dom2.mountFactory(() => {
  const which = ref('A')
  const Root = defineComponent({
    setup: () => ({ which }),
    render() {
      return h(KeepAlive, null, { default: () => (this.which === 'A' ? h(PageA) : h(PageB)) })
    },
  })
  return { component: Root, ctrl: { which } }
})
L('首次挂载                → ' + klog.join(' → ')); klog.length = 0
w.ctrl.which.value = 'B'; await nextTick()
L('切到B（A 只是隐藏）    → ' + klog.join(' → ')); klog.length = 0
w.ctrl.which.value = 'A'; await nextTick()
L('切回 A（没有重新挂载） → ' + klog.join(' → ') + '← 注意没有 A mount，它一直活着'); klog.length = 0
w.unmount()
L('销毁整个应用            → ' + klog.join(' → '))
L('')
L('★ 这就是 keep-alive 的全部含义：组件有「三个」状态而不是两个。')
L('  unmounted（真死） vs deactivated（活着但看不见）。')
L('  ★ 对应到 uni-app 的页面栈，机制完全一样：')
L('    navigateTo 离开 A 进 B → A 只是 onHide，**不卸载**；')
L('    reLaunch / 关掉 App → A 才 onUnload。')
L('  ★ 所以页面级请求放 onShow（每次显示都拉），不放 onLoad/onMounted（只跑一次）。')

