H('2. Vue 改写版（同一份功能）')
const dom = createMiniDom()
const { ctrl, root } = dom.mountFactory(() => {
  const rows = ref([])
  const kw = ref('')
  const loading = ref(false)
  const visible = computed(() => (kw.value ? rows.value.filter(r => r.name.includes(kw.value)) : rows.value))
  const onArchive = async (id) => {
    rows.value = rows.value.map(r => (r.id === id ? { ...r, isActive: false } : r))
  }
  const Panel = defineComponent({
    name: 'CategoryPanel',
    props: { familyId: { type: String, required: true } },
    setup(props) {
      // 首次拉取：对应 React 的 useEffect(..., [familyId])
      onMounted(async () => {
        loading.value = true
        rows.value = [
          { id: 'c-1', name: '餐饮', isActive: true },
          { id: 'c-2', name: '餐饮(家用)', isActive: true },
          { id: 'c-3', name: '停用的分类', isActive: false },
        ]
        loading.value = false
      })
      return () => h('view', { class: 'panel' }, [
        h('input', { value: kw.value, onInput: (e) => { kw.value = e.detail.value } }),
        loading.value ? h('text', '加载中') : null,
        ...visible.value.map((r) =>
          h('view', { key: r.id, class: r.isActive ? '' : 'off' }, [
            h('text', r.name),
            r.isActive ? h('text', { onClick: () => onArchive(r.id) }, '停用') : null,
          ])),
      ])
    },
  })
  return { component: Panel, ctrl: { rows, kw, loading, visible } }
}, { familyId: 'fam-1' })
// onMounted 里的 async 函数体要等微任务跑完，所以这里让出一次事件循环再渲染。
await new Promise((r) => setTimeout(r, 0))
L('（等onMounted 里的 await 跑完）')
L(render(root))

