// lab/s6/d09 —— 页面栈与导航 API：用 JS 把「页面栈」这根虚拟指针柱真的立起来
//
// 跑法：
//   cd ~/www/homecube/web && node lab/s6/d09/main.mjs
//
// uni-app 没有 DOM，页面的显示/隐藏由原生层按「栈顶是谁」决定。
// 所以要理解 navigateTo/redirectTo/switchTab/reLaunch，
// 只要把那个栈在 JS 里模拟出来，行为就完全确定了。

const L = (s = '') => console.log(s)
const H = (t) => L('\n===== ' + t + ' =====')

// 模拟器：栈底是启动页，栈顶是当前显示的页
class PageStack {
  constructor(home) { this.stack = [home]; this.log = [] }
  get top() { return this.stack[this.stack.length - 1] }
  get depth() { return this.stack.length }
  home() { return this.stack[0] }
  snapshot() { return this.stack.join(' → ') }

  navigateTo(url) {
    // 微信/uni-app 的硬限制：页面栈最多 10 层
    if (this.depth >= 10) {
      this.log.push('navigateTo ' + url + ' 失败：页面栈已达 10 层上限（微信与 uni-app 的硬限制）')
      return false
    }
    this.stack.push(url)
    this.log.push('navigateTo ' + url + '（入栈，深度 ' + this.depth + '）')
    return true
  }
  redirectTo(url) {
    this.stack.pop()
    this.stack.push(url)
    this.log.push('redirectTo ' + url + '（替换栈顶，深度不变 ' + this.depth + '）')
    return true
  }
  switchTab(url) {
    this.stack = [this.home(), url]
    this.log.push('switchTab ' + url + '（清空到只剩 启动页+目标，深度 2）')
    return true
  }
  reLaunch(url) {
    this.stack = [url]
    this.log.push('reLaunch ' + url + '（清空整栈，深度 1）')
    return true
  }
  navigateBack(delta = 1) {
    if (this.depth - 1 < delta) {
      this.log.push('navigateBack 失败：栈里只有 ' + this.depth + ' 层，退不了 ' + delta + ' 层')
      return false
    }
    for (let i = 0; i < delta; i++) this.stack.pop()
    this.log.push('navigateBack(' + delta + ') → ' + this.top + '（深度 ' + this.depth + '）')
    return true
  }
}

