// lab/s6/d10 —— 条件编译 #ifdef：写一个真的预处理器，把「编译期分支」跑出来
//
// 跑法：
//   cd ~/www/homecube/web && node lab/s6/d10/main.mjs
//
// 为什么要自己写这个预处理器：HBuilderX 里靠编译器裁剪，你在编辑器里看不到结果。
// 但条件编译的规则很短，短到可以完整实现一遍 —— 跑一遍你就真的懂它了。
//
// ★ 注意 #ifdef 必须**顶格**写（不能包在 // 注释里）。uni-app 的编译器是按行首关键字
//   识别的，写成 // #ifdef 会被当成普通注释，裁剪完全不生效 —— 这是最高频的踩坑。

const L = (s = '') => console.log(s)
const H = (t) => L('\n===== ' + t + ' =====')

// ---------- 迷你条件编译预处理器 ----------
// 规则（与 uni-app 官方一致）：
//   #ifdef 条件   → 条件为真时保留
//   #ifndef 条件  → 条件为假时保留
//   #else         → 切换
//   #endif        → 结束
//   条件用 || 连接
function preprocess(src, platform) {
  const out = []
  // 栈帧：{ keep } 本层是否保留；{ active } 本层已「命中」（用于 #else 取反）
  const stack = []
  const active = () => stack.every(f => f.active)

  for (const raw of src.split('\n')) {
    const line = raw.trim()
    const m = line.match(/^#(ifdef|ifndef|else|endif)\b\s*(.*)$/)

    if (!m) {                                   // 普通代码行
      if (active()) out.push(raw)
      continue
    }
    const [, kind, rest] = m

    if (kind === 'ifdef' || kind === 'ifndef') {
      const cond = rest.split('||').map(s => s.trim()).includes(platform)
      const hit = kind === 'ifdef' ? cond : !cond
      // 父层已失效时，本层无论条件如何都不保留
      stack.push({ hit, active: active() && hit })
    } else if (kind === 'else') {
      const top = stack[stack.length - 1]
      if (!top) throw new Error('#else 没有对应的 #ifdef')
      const parentActive = stack.slice(0, -1).every(f => f.active)
      top.active = parentActive && !top.hit          // 命中了就丢弃，没命中就保留
    } else {                                          // endif
      if (!stack.pop()) throw new Error('#endif 没有对应的 #ifdef')
    }
  }
  if (stack.length > 0) throw new Error('有 ' + stack.length + ' 个 #ifdef 没有 #endif 收尾')
  return out.join('\n')
}

