// lab/s6/d11 —— 请求层封装：baseURL、token 注入、401 处理（真打真HTTP 请求）
//
// 跑法：
//   cd ~/www/homecube/web && node lab/s6/d11/main.mjs
//
// 这份代码里没有一行假数据：请求真的发到了 127.0.0.1 上一个真的 HTTP 服务器，
// 服务端真的检查了 Authorization 头。输出里的「服务端看到 token=xxx」是它记下来的。

import { uni, storage, nav } from './mockuni.mjs'
import { startServer } from './server.mjs'

const L = (s = '') => console.log(s)
const H = (t) => L('\n===== ' + t + ' =====')

const { server, port, seen } = await startServer()
const BASE_URL = 'http://127.0.0.1:' + port

// ---------------- 请求层本体 ----------------
// 这一段就是工程里 web/src/utils/request.ts 的精简版，逻辑逐条对应。
class RequestError extends Error {
  constructor(status, message, body) { super(message); this.name = 'RequestError'; this.status = status; this.body = body }
}

function getToken() { const t = uni.getStorageSync('access_token'); return t || null }

let refreshing = null          // ★并发去重：多个请求同时 401 时，只发一次 refresh
let relaunching = false// ★ 跳登录页也要去重，否则并发 401 会连跳好几次

async function refreshAccessToken() {
  const rt = uni.getStorageSync('refresh_token')
  if (!rt) return false
  const res = await rawRequest('POST', '/api/homeos/auth/refresh', { refresh_token: rt })
  if (res.statusCode !== 200) return false
  // ★ 注意这里解构的层数：rawRequest 返回 {statusCode, data}，而契约里 refresh 接口
  //   是「裸回」{access_token, refresh_token}（不套信封）—— 所以字段在 res.data 里面。
  //   写成 res.access_token 会永远读到 undefined，于是 refresh「永远失败」→
  //   每次 401 都清 token 弹登录页。这类 bug 的特征就是：代码全对，但功能全废。
  const body = res.data
  if (body && body.access_token) {
    uni.setStorageSync('access_token', body.access_token)
    if (body.refresh_token) uni.setStorageSync('refresh_token', body.refresh_token)
    return true
  }
  return false
}

function rawRequest(method, url, data, header = {}) {
  return new Promise((resolve, reject) => {
    const headers = { 'Content-Type': 'application/json', ...header }
    const t = getToken()
    if (t) headers['Authorization'] = 'Bearer ' + t     // ★ token 注入：唯一出口
    uni.request({
      url: BASE_URL + url, method, header: headers, data,
      success: (res) => resolve({ statusCode: res.statusCode, data: res.data }),
      fail: (err) => reject(new RequestError(0, err.errMsg || '网络异常')),
    })
  })
}

async function request(method, url, data, { retried = false } = {}) {
  const res = await rawRequest(method, url, data)
  if (res.statusCode === 401) {
    // 第一次 401：静默换 token 再试一次（refresh 本身是 POST，不能走这条）
    if (!retried) {
      if (!refreshing) {
        refreshing = refreshAccessToken().finally(() => { refreshing = null })
      }
      const ok = await refreshing
      if (ok) return request(method, url, data, { retried: true })   // ★ 只重试一次
    }
    // ★ 到这里说明 refresh 也失败了：清 token + reLaunch 回登录页
    uni.removeStorageSync('access_token')
    uni.removeStorageSync('refresh_token')
    if (!relaunching) {                    // ★ 三个并发 401 只跳一次登录页
      relaunching = true
      uni.reLaunch({ url: '/pages/homeos/auth/login' })
      setTimeout(() => { relaunching = false }, 0)
    }
    throw new RequestError(401, '登录已过期，请重新登录', res.data)
  }
  if (res.statusCode >= 200 && res.statusCode < 300) return res.data
  throw new RequestError(res.statusCode, (res.data && res.data.message) || ('HTTP ' + res.statusCode), res.data)
}

const GET = (u) => request('GET', u)
const POST = (u, d) => request('POST', u, d)
const PUT = (u, d) => request('PUT', u, d)

// ---------------- 开跑 ----------------
H('1. 没有 token 时发请求：服务端看到什么')
try { await GET('/api/finance/categories') } catch (e) { L('  前端收到 ' + e.name + ' status=' + e.status + ' message=' + e.message) }
L('  服务端记到的请求：')
for (const s of seen) L('    ' + s.method + ' ' + s.url + '  Authorization=' + (s.token ? 'Bearer ' + s.token : '(无)'))

seen.length = 0
H('2. 有有效 token：token 被自动注入，业务数据正常回来')
uni.setStorageSync('access_token', 'tok-good')
const body = await GET('/api/finance/categories')
L('  服务端看到 token = ' + seen[0].token)
L('  返回 items 数量 = ' + body.items.length)
for (const c of body.items) L('    ' + (c.parent_id ? '  └ ' : '') + c.name + '  is_active=' + c.is_active + '  sort_order=' + c.sort_order)
L('  ★ 注意 is_active=false 的「停用的分类」也在列表里 —— 列表页要显示它（灰色），')
L('    只有「记账选择器」才过滤掉。这是 PRD 4.5.9 的口径，S7 d6 会用到。')

seen.length = 0
H('3. ★token 过期但 refresh 有效：静默换 token 并重试一次（用户无感）')
uni.setStorageSync('access_token', 'tok-old')      // 服务端已不认识这串
uni.setStorageSync('refresh_token', 'rt-1')
L('  调用前 access_token = ' + uni.getStorageSync('access_token') + '（服务端已不认识这串）')
const body2 = await GET('/api/finance/categories')
L('  调用后 access_token = ' + uni.getStorageSync('access_token') + '← 已自动换新')
L('  返回 items 数量 = ' + body2.items.length + '（用户完全没感觉到401发生过）')
L('  服务端一共收到 ' + seen.length + ' 个请求：')
seen.forEach((s, i) => L('    ' + (i + 1) + '. ' + s.method + ' ' + s.url + '  token=' + (s.token || '(无)')))
L('  ★ 第 1 个是业务请求（401），第 2 个是 refresh（换 token），第 3 个是重试的业务请求（200）。')
L('  ★ 这就是「拦截器」的价值：页面里写 GET(url) 完全不知道 token 过期这回事。')

seen.length = 0
H('4. ★并发去重：三个请求同时 401，只发一次 refresh')
uni.setStorageSync('access_token', 'tok-dead')
uni.setStorageSync('refresh_token', 'rt-invalid')      // 这串 refresh 也失效了
L('  并发发 3 个请求：')
const results = await Promise.allSettled([
  GET('/api/finance/categories'),
  GET('/api/finance/transactions'),
  GET('/api/finance/categories'),
])
results.forEach((r, i) => L('    请求' + (i + 1) + ' → ' + r.status + (r.reason ? '（' + r.reason.message + '）' : '')))
L('  服务端一共收到 ' + seen.length + ' 个请求：')
const refreshCount = seen.filter(s => s.url.includes('/auth/refresh')).length
L('    其中 refresh 请求 = ' + refreshCount + ' 个← 三个并发 401 只刷新了一次')
L('  ★ 没有这个去重的话，三个 401 会并发发三次 refresh；')
L('    真实服务端很可能在第二次 refresh 时就把 refresh_token 也作废了（轮换机制），')
L('    于是明明能续上的会话被自己搞挂。')

seen.length = 0
H('5. ★refresh 也失效：清 token + reLaunch 回登录页（本卡判据第 3 条）')
L('  刚才 reLaunch 记录：')
for (const [api, url] of nav) L('    ' + api + ' → ' + url)
L('  storage 里剩下的 key = ' + JSON.stringify([...storage.keys()]))
L('  access_token 被清掉了吗 → ' + (storage.has('access_token') ? '❌ 还在' : '✅ 已清'))
L('  ★ 为什么必须 reLaunch 而不是 navigateTo：')
L('    navigateTo 会把登录页压在一个已经 401 的页面之上。用户登录成功后按返回，')
L('    回到那个 401 页面，立刻又触发 401 → 又跳登录页 → 死循环。')
L('    reLaunch 清空整栈，登录页成为唯一页面，返回键无处可退，循环不成立。')

seen.length = 0
H('6. 业务错误（409 乐观锁冲突）不该触发重新登录')
uni.setStorageSync('access_token', 'tok-good')
uni.setStorageSync('refresh_token', 'rt-1')
try {
  await PUT('/api/finance/categories/c-1/archive', { version: 1 })
} catch (e) {
  L('  收到 ' + e.name + ' status=' + e.status + ' message=' + e.message)
}
L('  ★ 409 是「你的 version 旧了」，跟登录态无关。请求层必须只对 401 做重新登录，')
L('    否则用户改一次分类被抢占了，App 会把他踢回登录页。')
L('  ★ 这也是为什么需要 RequestError 带 status：只靠 message 字符串判断状态码，')
L('    等于把 HTTP 状态码重新解析一遍，改文案就崩。')

H('7. 请求层的三条纪律（本工程 utils/request.ts 的实际口径）')
L('  ① 出口契约是「裸响应体」：服务端 200 的 schema 就是业务对象本身，')
L('     所以调用方直接读 body.items，不要再 .data 剥一层。')
L('  ② token 注入只有一个出口（rawRequest 里那三行），页面代码永远不手写 Authorization。')
L('  ③ 401 才重新登录；其它 4xx/5xx 原样抛给调用方按 code 分支处理。')

server.close()

// lab/s6/d13 —— 为什么这段最快：把 7 天的东西对着真实工程文件自查一遍
//
// 跑法：
//   cd ~/www/homecube/web && node lab/s6/d13/main.mjs
//
// 这张卡不教新东西。它做一件事：把你「以为自己懂了」的东西，落到真实的工程文件上，
// 逐条检查。结果会告诉你哪几条是真懂、哪几条只是读过。

import { readFileSync, existsSync } from 'node:fs'
import { homedir } from 'node:os'
import { join } from 'node:path'
import { parse } from '@vue/compiler-sfc'

const L = (s = '') => console.log(s)
const H = (t) => L('\n===== ' + t + ' =====')

const WEB = join(homedir(), 'www/homecube/web')
const SRC = join(WEB, 'src')
const read = (p) => (existsSync(p) ? readFileSync(p, 'utf8') : null)

let pass = 0, fail = 0
function check(title, ok, detail) {
  if (ok) { pass++; L('  ✅ ' + title + (detail ? '  —— ' + detail : '')) }
  else { fail++; L('  ❌ ' + title + (detail ? '  —— ' + detail : '')) }
}

H('1. 工程现状（先确认你在对的目录上）')
L('web 目录 = ' + WEB + (existsSync(WEB) ? '（存在）' : '（不存在）'))
for (const p of ['pages.json', 'main.ts', 'App.vue', 'utils/request.ts', 'stores/home.ts']) {
  L('  ' + (existsSync(join(SRC, p)) ? '有' : '无') + '  src/' + p)
}

H('2. 逐条自查 W24-W25 的七条主张')
const pagesJsonRaw = read(join(SRC, 'pages.json'))
const pagesJson = pagesJsonRaw ? JSON.parse(pagesJsonRaw) : null
check('pages.json 里没有 tabBar 字段（双底栏禁令）',
  pagesJson && !Object.prototype.hasOwnProperty.call(pagesJson, 'tabBar'),
  pagesJson ? '实际字段：' + Object.keys(pagesJson).join(', ') : '读不到文件')
check('主包 pages 非空，且第一页是登录页或首页',
  pagesJson && pagesJson.pages.length > 0 &&
  /auth\/login|home\/index/.test(pagesJson.pages[0].path),
  pagesJson ? '第一页 = ' + pagesJson.pages[0].path : '')
check('finance 是分包（root = pages/finance）',
  pagesJson && (pagesJson.subPackages || []).some((sp) => sp.root === 'pages/finance'),
  pagesJson ? '分包 root = ' + (pagesJson.subPackages || []).map((s) => s.root).join(', ') : '')

const reqTs = read(join(SRC, 'utils/request.ts'))
check('请求层从 storage 取 token（不是 localStorage）',
  reqTs && /getStorageSync\(\s*['"]access_token['"]/.test(reqTs),
  reqTs ? (reqTs.match(/getStorageSync\(\s*['"]\w+['"]/g) || []).join(' ') : '')
check('token 以 Authorization 头注入（不是 Cookie）',
  reqTs && /Authorization/.test(reqTs) && !/document\.cookie/.test(reqTs))
check('401 分支存在且做了登出处理',
  reqTs && /401/.test(reqTs) && /removeStorageSync/.test(reqTs))
// 这一条不是「对不对」，是「现状是什么」——S6 判据要求的是 reLaunch，工程现状是 redirectTo，
// 差异原因见下一节的说明，所以这里只报告不判错。
if (reqTs) {
  const navApis = [...new Set(reqTs.match(/uni\.(navigateTo|redirectTo|reLaunch|switchTab)/g) || [])]
  const usesLaunch = /uni\.reLaunch/.test(reqTs)
  L('  ℹ️401 的跳转方式 = ' + (usesLaunch ? 'reLaunch（符合判据）' : navApis.join(', ') + '（与判据 reLaunch 有差异，见下一节）'))
}

const homeStore = read(join(SRC, 'stores/home.ts'))
check('shell 级状态用 pinia（defineStore）而不是模块级变量',
  homeStore && /defineStore/.test(homeStore))
check('store 里用的是 ref/computed（组合式），不是 options 的 data()',
  homeStore && /\bref\(/.test(homeStore) && /\bcomputed\(/.test(homeStore))

H('3. 扫全部 .vue 页面，找违反 uni-app 语法的写法')
const catPage = read(join(SRC, 'pages/finance/category/index.vue'))
if (catPage) {
  const { descriptor } = parse(catPage, { filename: 'category/index.vue' })
  const tpl = descriptor.template ? descriptor.template.content : ''
  check('category 页面能被 SFC 解析（无语法错误）', true,
    'template ' + tpl.split('\n').length + ' 行')
  // ★ 注意：<button> 是 uni-app 的合法内置组件（带 open-type 等原生能力），
  //   不能把它算进违规项。真正不被支持的是 HTML 语义标签 div/span/img/p/h1。
  const badTags = tpl.match(/<(div|span|img|p|h1|h2)\b/g)
  check('template 里没有 HTML 语义标签（div/span/img/p/h1 会导致 App 端编译失败）',
    !badTags,
    badTags ? '发现：' + [...new Set(badTags)].join(', ') : '未发现')
  check('用到的内置组件都在 uni-app 支持清单内',
    !/<(\w+)[\s>]/.test(tpl) || [...new Set(tpl.match(/<(\w+)[\s>]/g).map((s) => s.slice(1).replace(/[\s>]$/, '')))]
      .every((t) => ['view', 'text', 'button', 'input', 'scroll-view', 'image', 'template', 'block'].includes(t)),
    '本页用到的：' + [...new Set((tpl.match(/<(\w+)[\s>]/g) || []).map((s) => s.slice(1).replace(/[\s>]$/, '')))].join(', '))
  check('v-for 用了 :key 而不是 index',
    !/:key="(?:i|idx|index)\b/.test(tpl))
  check('script 段是 <script setup>',
    !!descriptor.scriptSetup)
} else {
  L('  （跳过：category/index.vue 不存在）')
  fail += 5
}

H('4. ★顺带发现的一个真实问题：401 用的是 redirectTo，不是 reLaunch')
L('工程现状：utils/request.ts 的 401 分支调用的是 uni.redirectTo({url: login})')
L('S6 判据要求：uni.reLaunch({url: login})')
L('')
L('两者对页面栈的影响（d09 第 5 节真跑过）：')
const stackDemo = (api) => {
  const st = ['首页', '财务/分类', '财务/添加流水']
  if (api === 'redirectTo') st.splice(2, 1, '登录页')
  else { st.length = 0; st.push('登录页') }
  return st.join(' → ')
}
L('  用 redirectTo：' + stackDemo('redirectTo'))
L('  用 reLaunch ：' + stackDemo('reLaunch'))
L('')
L('★ 差别：redirectTo 只换掉栈顶，于是「登录页」下面还压着那个已401 的页面。')
L('  用户登录成功进入首页后按返回键，会回到那个旧页面，它立刻再次触发 401。')
L('  如果那个页面在 onShow 里拉数据，就会出现「登录 → 返回 → 又跳登录」的循环。')
L('  reLaunch 清空整栈，登录页之下无处可退，循环不成立。')
L('')
L('★ 这不是「现在就会崩」—— 首页是主包第一页、返回栈通常很短，所以线上未必复现。')
L('  但它是判据第 3 条明确要求的那一类问题，属于「现在没炸、扩一个页面就炸」。')
L('  S7 d11联调时如果你从「财务/添加流水」这类深层页面遇到 401，就亲历这个循环了。')

H('5. 数一数：这一周你实际要写的代码量')
const rows = [
  ['一个页面（.vue）', '80~200 行', '对照 React 同功能页面通常 120~250 行'],
  ['一个请求层封装', '60~120 行', 'd11 那份，token + 401 + 并发去重'],
  ['一个 pages.json 改动', '1~5 行', '只是加一条 path，但它决定页面能不能被访问'],
  ['条件编译一处', '3~6 行', '只在「平台能力不同」时才写'],
]
L('产出'.padEnd(24) + '典型行数'.padEnd(14) + '备注')
for (const [a, b, c] of rows) L(a.padEnd(22) + b.padEnd(12) + c)
L('')
L('★ 对比 S5（权限，34 张卡）：那边每一张都在补一条安全边界；')
L('  这边每一张都在把「你已经会的 React 心智」翻译成 Vue 写法。')
L('  所以这段系数是 0.8——不是「简单」，是「你不需要重新学一套思考方式」。')

H('6. ★但这段有三个「反直觉」，比知识点更值得记')
const traps = [
  ['watch(ref 装对象) 不写 deep 就不触发', 'd03 实测'],
  ['// #ifdef 写在注释里完全不裁剪', 'd10 实测'],
  ['改 toRaw 拿到的原始对象，值变了但界面不更新', 'd03 实测'],
]
L('坑'.padEnd(46) + '来源')
for (const [a, b] of traps) L(a.padEnd(44) + b)
L('')
L('★ 这三个都不是「API 记错了」，而是「你对响应式的模型想错了」。')
L('  所以这段真正要带走的不是语法，是这个模型：')
L('  Vue 在「你读属性」的那一刻记下依赖，只有通过代理读才会被记录。')

H('7. 自查结论')
L('通过 ' + pass + ' 条，失败 ' + fail + ' 条')
if (fail === 0) {
  L('★ 全部通过。W25 结束时你应该能独立回答 S6 的三条通过判据。')
} else {
  L('★ 有 ' + fail + ' 条没过。上面标❌ 的那几条，回去看对应那天的 lab 脚本重跑一遍。')
}

