H('判据二：能改 —— 三个当场可判的需求，你写对了吗')
// 需求 1：搜索要「自己的名或父级的名 命中即可」
const rows = ref([
  { id: '1', name: '餐饮', parent_id: null, is_active: true, sort_order: 10 },
  { id: '2', name: '买菜', parent_id: '1', is_active: true, sort_order: 11 },
  { id: '3', name: '交通', parent_id: null, is_active: true, sort_order: 12 },
])
const parentName = (id) => (rows.value.find((r) => r.id === id) || {}).name || ''
const kw = ref('餐饮')
// 错误写法：只匹配自己的名
const wrong = computed(() => rows.value.filter((r) => r.name.includes(kw.value)))
// 正确写法：自己的名 或 父级的名 命中即可
const right = computed(() => {
  const k = kw.value.trim()
  if (!k) return rows.value
  return rows.value.filter((r) => r.name.includes(k) || parentName(r.parent_id).includes(k))
})
L('需求1：搜索「餐饮」时，「买菜」虽然自己不含这个词，但它的父级叫「餐饮」，应该被搜出来')
L('  错误写法（只匹配自己）→ ' + JSON.stringify(wrong.value.map((r) => r.name)) + '   ← 漏了「买菜」')
L('  正确写法（自己也匹配父名）→ ' + JSON.stringify(right.value.map((r) => r.name)) + ' ← 两条都在')
verdict(wrong.value.length === 1 && right.value.length === 2, '需求1：两种写法结果确实不同，正确写法多搜出「买菜」')

// 需求 2：列表要显示停用项，但记账选择器不显示
const listAll = computed(() => rows.value)                                 // 列表：全显示
const pickerOnly = computed(() => rows.value.filter((r) => r.is_active))  // 选择器：只显示启用
rows.value[2].is_active = false                                           // 停用「交通」
L('')
L('需求2：先停用「交通」，然后——')
L('  列表页 items  = ' + JSON.stringify(listAll.value.map((r) => r.name)) + ' ← 含停用项（灰显）')
L('  选择器 items = ' + JSON.stringify(pickerOnly.value.map((r) => r.name)) + ' ← 不含停用项')
verdict(listAll.value.length === 3 && pickerOnly.value.length === 2, '需求2：列表与选择器用了不同的过滤条件')

// 需求 3：拖拽排序后要把新顺序写回服务端
const ids = ref(['1', '2', '3'])
async function saveSort(newOrder) {
  return { items: newOrder.map((id, i) => ({ id, sort_order: (i + 1) * 10 })) }
}
const moved = [...ids.value].reverse()
ids.value = moved
const saved = await saveSort(moved)
L('')
L('需求3：把顺序 [1,2,3] 拖成倒序 [3,2,1]，然后提交给服务端')
L('  前端新的顺序 = ' + JSON.stringify(ids.value))
L('  提交 payload  = ' + JSON.stringify(saved))
L('  ★ payload 里是 **id** + 重排后的 sort_order（10/20/30），不是数组下标。')
L('    因为服务端要的是「顺序值」，而前端数组下标只是临时位置。')
verdict(saved.items.map((x) => x.id).join(',') === '3,2,1'
       && saved.items.map((x) => x.sort_order).join(',') === '10,20,30',
  '需求3：提交的是 id + 重排后的 sort_order，且两者方向一致')

H('判据三：能定位 bug —— 四段有问题的代码，错在哪')
const bugs = [
  {
    title: '① watch 不触发',
    code: "const list = ref([])\nwatch(list, () => console.log('变了'))\nlist.value.push('a')   // 不打印",
    why: 'watch(ref 装数组) 不写 deep 时，只比较 .value 指针。push 不换指针 → 不触发。修法：加 { deep: true } 或改 list.value = [...list.value, "a"]。',
  },
  {
    title: '② 界面不更新但打印是对的',
    code: "const st = reactive({ n: 0 })\nst.n = 1                 // n 变了\ntoRaw(st).m = 2        // 改了原始对象",
    why: 'toRaw 绕过了 Proxy，Vue 完全不知情。d03 实测：值确实变了、界面不更新。修法：永远别用 toRaw 改数据。',
  },
  {
    title: '③ App 端白屏，H5 正常',
    code: '<view>{{ x }}</view>\n<script>document.querySelector(".x")</script>',
    why: 'App 端没有 document。这行会抛 ReferenceError，整个页面渲染中断 → 白屏。修法：uni.createSelectorQuery()。',
  },
  {
    title: '④ 请求层死循环',
    code: 'if (res.statusCode === 401) {\n  uni.navigateTo({ url: \'/pages/homeos/auth/login\' })\n}',
    why: '登录页压在 401 页之上；登录完返回又触发 401。修法：reLaunch 清空整栈（判据第 3 条）。',
  },
]
for (const b of bugs) {
  L('')
  L(b.title)
  b.code.split('\n').forEach((l) => L('    ' + l))
  L('  错在：' + b.why)
}
